settings.custom_liquid:
{%- comment -%}
  Навигационна пътека (breadcrumbs) за pamaura.com — изискване на ПКИП
  „Изградено базово SEO — минимум SEF URLs, Breadcrumps и мета данни“.
  Поставя се ВЕДНЪЖ, в секция „Custom Liquid“ в HEADER GROUP на темата.
  Header group е общ за всички страници, а продуктите на pamaura.com ползват
  7 различни шаблона (cocoa-glow-v2, premium-coconut-cleanse-new, …) — нито
  един не е „Default product“. Показва се само на продукти и колекции.
  Продукт, отворен от колекция:  Начало › Колекция › Продукт
  Продукт, отворен директно:     Начало › Продукт
  Колекция:                      Начало › Колекция
{%- endcomment -%}
{%- liquid
  if request.locale.iso_code == 'ro'
    assign home_label = 'Acasă'
  else
    assign home_label = 'Начало'
  endif
-%}
{%- if product or collection -%}
<nav class="pkip-breadcrumbs" aria-label="breadcrumb">
  <a href="{{ routes.root_url }}">{{ home_label }}</a>
  {%- if collection -%}
    <span class="sep" aria-hidden="true">›</span>
    {%- if product -%}
      <a href="{{ collection.url }}">{{ collection.title }}</a>
    {%- else -%}
      <span aria-current="page">{{ collection.title }}</span>
    {%- endif -%}
  {%- endif -%}
  {%- if product -%}
    <span class="sep" aria-hidden="true">›</span>
    <span aria-current="page">{{ product.title }}</span>
  {%- endif -%}
</nav>
{%- endif -%}
<style>
  .pkip-breadcrumbs{max-width:1400px;margin:16px auto 0;padding:0 40px;font-size:14px;line-height:1.5;color:#8a7866}
  .pkip-breadcrumbs a{color:#8a7866;text-decoration:none}
  .pkip-breadcrumbs a:hover{text-decoration:underline}
  .pkip-breadcrumbs .sep{margin:0 8px}
  .pkip-breadcrumbs [aria-current]{color:#4a3627}
  @media (max-width:749px){.pkip-breadcrumbs{padding:0 16px;font-size:13px}}
</style>
